sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
       // gs.info('Business Rule Execution Started.');

        // Fetch the groups the creator belongs to
        var creatorSysID = current.getValue('opened_by');
       //gs.info('Creator sys_id: ' + creatorSysID);

        var creatorGroups = getUserGroups(creatorSysID);
        //gs.info('Creator Groups: ' + JSON.stringify(creatorGroups));

        if (!creatorGroups || creatorGroups.length === 0) {
            //gs.info('No groups found for the user creating the record.');
            return;
        }

        // Extract the instance identifier from the group names
        var instanceIdentifier = extractInstanceIdentifier(creatorGroups);
        if (!instanceIdentifier) {
            //gs.info('No instance identifier found in the user groups.');
            return;
        }
        //gs.info('Using Instance Identifier: ' + instanceIdentifier);

        // Fetch and process the email list
        var emailList = current.getValue('prm_user_email_lst');
        //gs.info('Fetched Email List: ' + emailList);

        if (!emailList || emailList.trim() === '') {
            //gs.info('prm_user_email_lst field is empty or undefined.');
            return;
        }

        var emailArray = emailList.split(',').map(email => email.trim());
       // gs.info('Email Array after splitting and trimming: ' + JSON.stringify(emailArray));

        // Determine approver roles based on creator's groups and state
        var approverRoles = determineApproverRoles(creatorGroups, current.getValue('state'), instanceIdentifier);
        //gs.info('Approver Roles determined: ' + approverRoles.join(','));

        // Filter email IDs based on approver roles
        var filteredEmails = filterEmailsByRoles(emailArray, approverRoles);
       // gs.info('Filtered Emails: ' + filteredEmails.join(','));

        var refRec = current.receiving_country_territory.getRefRecord(); // Fetch the referenced record using 
        var countryCode = refRec.getValue('iso3166_2');


        //gs.info('Country Code mapped from receiving_country_territory: ' + countryCode);

        // Define product_team variable
        var productTeam = current.getValue('receiving_product_team');

        // State-specific logic
        if (current.getValue('state') === '8') {
           // gs.info(`State is 8, filtering users from groups Infodir-iQube-${instanceIdentifier}-PRM-SglApprvr and Infodir-iQube-${instanceIdentifier}-ReqrProc.`);

            var state8Emails = getEmailsFromGroups([
                `Infodir-iQube-${instanceIdentifier}-PRM-SglApprvr`,
                `Infodir-iQube-${instanceIdentifier}-PRM-ReqrProc`
            ]);
           // gs.info('State 8 emails: ' + state8Emails);

            // Fetch emails for individual groups
            var group1Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-HBAP-${countryCode}`]);
            var group2Emails = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-${productTeam}`]);

            // Calculate the intersection of emails present in both groups
            var additionalEmails = group1Emails.filter(email => group2Emails.includes(email));
            //gs.info('Emails present in both groups: ' + additionalEmails);

            // Filter users to ensure they are part of both the state-specific groups and the additional groups
            filteredEmails = state8Emails.filter(email => additionalEmails.includes(email));
            //gs.info('Filtered emails for state 8: ' + filteredEmails.join(','));
        }

        if (current.getValue('state') === '9') {
            //gs.info(`State is 9, filtering users from group Infodir-iQube-${instanceIdentifier}-PRM-Apprvr.`);

            var state9Emails = getEmailsFromGroups([
                `Infodir-iQube-${instanceIdentifier}-PRM-Apprvr`
            ]);
            //gs.info('State 9 emails: ' + state9Emails);

            // Fetch emails for individual groups
            var group1EmailsState9 = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-HBAP-${countryCode}`]);
            var group2EmailsState9 = getEmailsFromGroups([`Infodir-iQube-${instanceIdentifier}-PRM-${productTeam}`]);

            // Calculate the intersection of emails present in both groups
            var additionalEmailsState9 = group1EmailsState9.filter(email => group2EmailsState9.includes(email));
           // gs.info('Emails present in both groups for state 9: ' + additionalEmailsState9);

            // Filter users to ensure they are part of both the state-specific groups and the additional groups
            filteredEmails = state9Emails.filter(email => additionalEmailsState9.includes(email));
           // gs.info('Filtered emails for state 9: ' + filteredEmails.join(','));
        }

        // Remove duplicates from the email list
        filteredEmails = [...new Set(filteredEmails)];
        //gs.info('Final filtered email list after removing duplicates: ' + filteredEmails.join(','));

        // Update the field with the filtered email list
        current.setValue('prm_user_email_lst', filteredEmails.join(','));
        current.update();
        //gs.info('Updated prm_user_email_lst field with filtered emails: ' + filteredEmails.join(','));

        //gs.info('Business Rule Execution Completed.');
    } catch (err) {
        gs.error('Error filtering email list: ' + err.message + '\n' + err.stack);
    }

    // ========= Helper Functions =========

    function getUserGroups(userSysID) {
        //gs.info('Fetching groups for user sys_id: ' + userSysID);
        var groups = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('user', userSysID);
        gr.query();
        while (gr.next()) {
            groups.push({
                sys_id: gr.group.sys_id.toString(),
                name: gr.group.name.toString()
            });
        }
        //gs.info('Total groups fetched for user: ' + groups.length);
        return groups;
    }

    function extractInstanceIdentifier(groups) {
       // gs.info('Extracting instance identifier from group names.');
        for (var i = 0; i < groups.length; i++) {
            var match = groups[i].name.match(/^Infodir-iQube-([A-Za-z0-9-]+)-PRM/);
            if (match && match[1]) {
                return match[1];
            }
        }
        return null;
    }

    function determineApproverRoles(creatorGroups, state, instanceIdentifier) {
       // gs.info('Determining approver roles based on creator groups and state: ' + state);
        var approverRoles = [];
        var creatorRoleNames = creatorGroups.map(group => group.name);

        creatorRoleNames.forEach(role => {
            if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ReqrNAUTH-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
                if (state === '7') {
                    approverRoles = [`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L2Apprvr`];
                }
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
            } else if (role === `Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-Reqr`) {
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrAsigner-L1Apprvr`);
                approverRoles.push(`Infodir-iQube-${instanceIdentifier}-PRM-ApprvrBsigner-L1Apprvr`);
            }
        });
        return approverRoles;
    }

    function filterEmailsByRoles(emailArray, approverRoles) {
       // gs.info('Filtering emails based on approver roles.');
        var filteredEmails = [];
        var gr = new GlideRecord('sys_user');
        gr.addQuery('email', 'IN', emailArray.join(','));
        gr.query();
        while (gr.next()) {
            var userGroups = getUserGroups(gr.sys_id.toString());
            var userRoleNames = userGroups.map(group => group.name);
            if (approverRoles.some(role => userRoleNames.includes(role))) {
                filteredEmails.push(gr.email.toString());
            }
        }
        return filteredEmails;
    }

    function getEmailsFromGroups(groupNames) {
        //gs.info('Fetching emails for groups: ' + groupNames.join(','));
        var emails = [];
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group.name', 'IN', groupNames.join(','));
        gr.query();
        while (gr.next()) {
            var userEmail = gr.user.email.toString();
            if (userEmail) {
                emails.push(userEmail);
            }
        }
        return emails;
    }
})(current, previous);
